+ * Apply one click event: create/resolve the contact (visitor cookie id),
+ * insert the ContentTouch row, then recompute the contact's lifecycle stage
+ * and persona stats. All inside one transaction — a failed recompute must not
+ * lose the touch.
+ */
+export async function applyClick(
+  prisma: PrismaClient,
+  event: ClickEvent,
+): Promise<void> {
+  const variant = await prisma.postVariant.findUnique({
+    where: { id: event.variantId },
+    include: { channel: true },
+  });
+  if (!variant) throw new Error(`unknown variant ${event.variantId}`);
+
+  await prisma.$transaction(async (tx) => {
+    let contactId: string | null = null;
+    if (event.contactId) {
+      // Upsert (not create) — two parallel clicks from the same new visitor
+      // cookie can race; the cookie id doubles as the contact id.
+      const contact = await tx.contact.upsert({
+        where: { id: event.contactId },
+        create: {
+          id: event.contactId,
+          workspaceId: event.workspaceId,
+          type: "AUDIENCE",
+          profileSourceChannel: variant.channel.slug,
+        },
+        update: {},
+      });
+      contactId = contact.id;
+    }
+    await tx.contentTouch.create({
+      data: {
+        contactId,
+        postId: event.postId,
+        variantId: event.variantId,
+        action: event.action ?? "CLICK",
+      },
+    });
+    if (contactId) {
+      await recomputeContactState(tx, contactId);
+    }
+  });
+}
+
+async function recomputeContactState(
+  tx: Parameters<Parameters<PrismaClient["$transaction"]>[0]>[0],
+  contactId: string,
+): Promise<void> {
+  const engageSince = new Date(Date.now() - ENGAGE_WINDOW_DAYS * 86_400_000);
+  const distinctPosts = await tx.contentTouch.findMany({
+    where: { contactId, timestamp: { gte: engageSince } },
+    select: { postId: true },
+    distinct: ["postId"],
+  });
