+  await tx.contact.update({
+    where: { id: contactId },
+    data: {
+      stateLifecycleStage: stage,
+      personaContentDNA: {
+        actionCounts,
+        distinctPosts: distinctPosts.length,
+        windowDays: PERSONA_WINDOW_DAYS,
+        derivedAt: new Date().toISOString(),
+      },
+    },
+  });
+}
